
@ormcache("self.env.uid", "model_name")
def per_user(self, model_name): ...

@ormcache("self.env.access_signature", "self.env.lang")
def per_signature(self): ...

@tools.ormcache("frozenset(self.env.user._get_group_ids())")
def per_groups(self): ...

@tools.ormcache("self.env.su", "self.env.user.share")
def per_share(self): ...

@tools.ormcache("self.id", "key", cache="memberships")
def cleared_by_a_membership(self, key): ...

@tools.ormcache("uid", "passwd_hash")
def per_credential(self, uid, passwd_hash): ...

@ormcache("self.env.lang")
def per_language(self): ...

@ormcache("self._uid")
def per_private_uid(self): ...
